    aiLogStream stream = aiGetPredefinedLogStream(aiDefaultLogStream_STDOUT,NULL);
    aiAttachLogStream(&stream);

    Importer importer;
    const aiScene *sc = importer.ReadFileFromMemory(data, dataSize,
